import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface SqueezeInProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  stagger?: number;
  squeeze?: number;
  speed?: number;
  className?: string;
}

const SQUEEZE_FRAMES = 16;

function squeezeInLength(text: string, stagger = 3): number {
  const chars = Array.from(text);
  if (chars.length === 0) return 0;
  return chars.length * stagger + SQUEEZE_FRAMES;
}

const squeezeEasing = Easing.out(Easing.cubic);

function SqueezeInBase({
  text,
  fontSize = 72,
  color = "#171717",
  fontWeight = 400,
  stagger = 3,
  squeeze = 0.03,
  speed = 1,
  className,
}: SqueezeInProps) {
  const frame = useCurrentFrame() * speed;

  const chars = Array.from(text);
  const lastRevealAt = chars.length * stagger;

  const squeezeProgress = interpolate(
    frame,
    [lastRevealAt, lastRevealAt + SQUEEZE_FRAMES],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: squeezeEasing,
    },
  );

  const gap = squeeze * fontSize * (1 - squeezeProgress);
  const wipe = interpolate(frame, [0, lastRevealAt], [100, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const anchorX =
    (-squeeze * fontSize * squeezeProgress * (chars.length - 1)) / 2;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        whiteSpace: "nowrap",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          translate: `${anchorX}px 0`,
          clipPath: `inset(-0.2em ${wipe}% -0.25em -0.1em)`,
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.02em",
          lineHeight: 1.1,
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
        }}
      >
        {chars.map((char, j) => (
          <span
            key={j}
            style={{
              display: "inline-block",
              whiteSpace: "pre",
              marginRight: j < chars.length - 1 ? gap : undefined,
            }}
          >
            {char}
          </span>
        ))}
      </span>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Remocn",
    description: "Text",
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 160,
    step: 1,
    default: 72,
    description: "Font size",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    min: 1,
    max: 8,
    step: 1,
    default: 3,
    description: "Frames / char",
    hiddenFromList: false,
  },
  squeeze: {
    type: "number",
    min: 0,
    max: 0.2,
    step: 0.01,
    default: 0.03,
    description: "Extra gap (em)",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#171717",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "400",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  width: {
    type: "number",
    default: 620,
    min: 10,
    step: 10,
    description: "Width",
  },
  height: {
    type: "number",
    default: 110,
    min: 10,
    step: 10,
    description: "Height",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","fontSize","stagger","squeeze","color","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Remocn",
  fontSize: 72,
  stagger: 3,
  squeeze: 0.03,
  color: "#171717",
  fontWeight: "400",
  speed: 1,
};

type SqueezeInElementProps = InteractiveBaseProps &
  InteractiveTransformProps & { readonly width?: number; readonly height?: number } &
  ComponentProps<typeof SqueezeInBase>;

const SqueezeInInner = forwardRef<
  HTMLDivElement,
  SqueezeInElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, width = 620, height = 110, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SqueezeIn>"}
      outlineRef={outlineRef}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          ref={outlineRef}
          style={{
            position: "relative",
            width,
            height,
            ...style,
          }}
        >
          <SqueezeInBase
            {...(componentProps as unknown as ComponentProps<typeof SqueezeInBase>)}
          />
        </div>
      </div>
    </Sequence>
  );
});

export const SqueezeIn = Interactive.withSchema({
  Component: SqueezeInInner,
  componentName: "<SqueezeIn>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
